import{_ as o,a0 as i,w as d,s as r,ao as t,I as l,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"淺述內核中“掛起到空閒”的實現 | LCTT x X-CMD","titleTemplate":false,"description":"淺述內核中“掛起到空閒”的實現 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"淺述內核中“掛起到空閒”的實現 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"淺述內核中“掛起到空閒”的實現 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20161018 Suspend to Idle","title":"淺述內核中“掛起到空閒”的實現","tag":"201703","desc":""},"relativePath":"201703/20161018 Suspend to Idle.md","filePath":"[post].md"}'),c={name:"201703/20161018 Suspend to Idle.md"};function u(m,s,h,g,f,b){const a=i("Link");return d(),r("div",null,[s[18]||(s[18]=t('<h1 id="淺述內核中-掛起到空閒-的實現" tabindex="-1">淺述內核中“掛起到空閒”的實現 <a class="header-anchor" href="#淺述內核中-掛起到空閒-的實現" aria-label="Permalink to “淺述內核中“掛起到空閒”的實現”">​</a></h1><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>Linux 內核提供了多種睡眠狀態，各個狀態通過設置系統中的不同部件進入低耗電模式來節約能源。目前總共有四種睡眠狀態，分別是：掛起到空閒（suspend to idle）、加電待機（power-on standby（standby））、掛起到內存（suspend to ram）和掛起到磁盤（suspend to disk）。這些狀態分別對應 ACPI 的 4 種狀態：S0，S1，S3 和 S4。掛起到空閒（suspend to idle）是純軟件實現的，用於將 CPU 維持在儘可能深的 idle 狀態。加電待機（power-on standby（standby））則使設備處於低功耗狀態，並且關閉所有非引導 CPU。掛起到內存（suspend to ram）就更進一步，關閉所有 CPU 並且設置 RAM 進入自刷新模式。掛起到磁盤（suspend to disk）則是最省功耗的模式，關閉儘可能多的系統，包括關閉內存。然後內存中的內容會被寫到硬盤，待喚醒計算機的時候將硬盤中的內容重新恢復到內存中。</p><p>這篇博文主要介紹掛起到空閒（suspend to idle）的實現。如上所説，它主要通過軟件實現。一般平台的掛起過程包括凍結用户空間並將外圍設備調至低耗電模式。但是，系統並不是直接關閉和熱插拔掉 CPU，而是靜靜地強制將 CPU 進入空閒（idle）狀態。隨着外圍設備進入了低耗電模式，除了喚醒相關的中斷外不應有其他中斷產生。喚醒中斷包括那些設置用於喚醒系統的計時器（比如 RTC，普通計時器等）、或者電源開關、USB 和其它外圍設備等。</p><p>在凍結過程中，當系統進入空閒狀態時會調用一個特殊的 cpu 空閒函數。這個 <code>enter_freeze()</code> 函數可以和調用使 cpu 空閒的 <code>enter()</code> 函數一樣簡單，也可以複雜得多。該函數複雜的程度由將 SoC 置為低耗電模式的條件和方法決定。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><h4 id="platform-suspend-ops" tabindex="-1"><code>platform_suspend_ops</code> <a class="header-anchor" href="#platform-suspend-ops" aria-label="Permalink to “platform_suspend_ops”">​</a></h4><p>一般情況，為了支持 S2I，系統必須實現 <code>platform_suspend_ops</code> 並提供最低限度的掛起支持。這意味着至少要完成 <code>platform_suspend_ops</code> 中的 <code>valid()</code> 函數。如果掛起到空閒（suspend to idle）和掛起到內存（suspend to ram）都要支持，valid 函數中應使用 <code>suspend_valid_only_mem</code>。</p>',8)),l("p",null,[s[1]||(s[1]=e("不過，最近內核增加了對 S2I 的自動支持。Sudeep Holla 提出了一個變更，可以讓系統不需要滿足 ",-1)),s[2]||(s[2]=l("code",null,"platform_suspend_ops",-1)),s[3]||(s[3]=e(" 條件也能提供 S2I 支持。這個補丁已經被接收並將合併在 4.9 版本中，該補丁可從這裏獲取： ",-1)),n(a,{href:"https://lkml.org/lkml/2016/8/19/474"},{default:p(()=>[...s[0]||(s[0]=[e("https://lkml.org/lkml/2016/8/19/474",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[19]||(s[19]=t(`<p>如果定義了 <code>suspend_ops</code>，那麼可以通過查看 <code>/sys/power/state</code> 文件得知系統具體支持哪些掛起狀態。如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/power/state</span></span>
<span class="line"><span>freeze mem</span></span></code></pre></div><p>這個示例的結果顯示該平台支持 S0（掛起到空閒（suspend to idle））和 S3（掛起到內存（suspend to ram））。按 Sudeep 的變更，那些沒有實現 <code>platform_suspend_ops</code> 的平台將只顯示 freeze 狀態。</p><h4 id="喚醒中斷" tabindex="-1">喚醒中斷 <a class="header-anchor" href="#喚醒中斷" aria-label="Permalink to “喚醒中斷”">​</a></h4><p>一旦系統處於某種睡眠狀態，系統必須要接收某個喚醒事件才能恢復系統。這些喚醒事件一般由系統的設備產生。因此一定要確保這些設備驅動使用喚醒中斷，並且將自身配置為接收喚醒中斷後產生喚醒事件。如果沒有正確識別喚醒設備，系統收到中斷後會繼續保持睡眠狀態而不會恢復。</p><p>一旦設備正確實現了喚醒接口的調用，就可用來生成喚醒事件。請確保 DT 文件正確配置了喚醒源。下面是一個配置喚醒源示例，該文件來自（<code>arch/arm/boot/dst/am335x-evm.dts</code>）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>     gpio_keys: volume_keys@0 {</span></span>
<span class="line"><span>               compatible = “gpio-keys”;</span></span>
<span class="line"><span>               #address-cells = &lt;1&gt;;</span></span>
<span class="line"><span>               #size-cells = &lt;0&gt;;</span></span>
<span class="line"><span>               autorepeat;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               switch@9 {</span></span>
<span class="line"><span>                       label = “volume-up”;</span></span>
<span class="line"><span>                       linux,code = &lt;115&gt;;</span></span>
<span class="line"><span>                       gpios = &lt;&amp;gpio0 2 GPIO_ACTIVE_LOW&gt;;</span></span>
<span class="line"><span>                       wakeup-source;</span></span>
<span class="line"><span>               };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               switch@10 {</span></span>
<span class="line"><span>                       label = “volume-down”;</span></span>
<span class="line"><span>                       linux,code = &lt;114&gt;;</span></span>
<span class="line"><span>                       gpios = &lt;&amp;gpio0 3 GPIO_ACTIVE_LOW&gt;;</span></span>
<span class="line"><span>                       wakeup-source;</span></span>
<span class="line"><span>               };</span></span>
<span class="line"><span>       };</span></span></code></pre></div><p>如上所示，有兩個 gpio 鍵被配置為喚醒源，在系統掛起期間，其中任何一個鍵被按下都會產生一個喚醒事件。</p><p>可替代 DT 文件配置的另一個喚醒源配置就是設備驅動，如果設備驅動自身在代碼裏面配置了喚醒支持，那麼就會使用該默認喚醒配置。</p><h3 id="實施" tabindex="-1">實施 <a class="header-anchor" href="#實施" aria-label="Permalink to “實施”">​</a></h3><h4 id="凍結功能" tabindex="-1">凍結功能 <a class="header-anchor" href="#凍結功能" aria-label="Permalink to “凍結功能”">​</a></h4><p>如果系統希望能夠充分使用掛起到空閒（suspend to idle），那麼應該在 CPU 空閒驅動代碼中定義 <code>enter_freeze()</code> 函數。<code>enter_freeze()</code> 與 <code>enter()</code> 的函數原型略有不同。因此，不能將 <code>enter()</code> 同時指定給 <code>enter</code> 和 <code>enter_freeze</code>。至少，系統會直接調用 <code>enter()</code>。如果沒有定義 <code>enter_freeze()</code>，系統會掛起，但是不會觸發那些只有當 <code>enter_freeze()</code> 定義了才會觸發的函數，比如 <code>tick_freeze()</code> 和 <code>stop_critical_timing()</code> 都不會發生。這會導致計時器中斷喚醒系統，但不會導致系統恢復，因為系統處理完中斷後會繼續掛起。</p><p>在掛起過程中，中斷越少越好（最好一個也沒有）。</p><p>下圖顯示了能耗和時間的對比。圖中的兩個尖刺分別是掛起和恢復。掛起前後的能耗尖刺是系統退出空閒態進行記錄操作，進程調度，計時器處理等。因延遲的緣故，系統進入更深層次空閒狀態需要花費一段時間。</p><p><img src="http://www.linaro.org/wp-content/uploads/2016/10/blog-picture-one-1024x767.png" alt="blog-picture-one"></p><p><em>能耗使用時序圖</em></p><p>下圖為 ftrace 抓取的 4 核 CPU 在系統掛起和恢復操作之前、之中和之後的活動。可以看到，在掛起期間，沒有請求或者中斷被處理。</p><p><img src="http://www.linaro.org/wp-content/uploads/2016/10/blog-picture-2-1024x577.png" alt="blog-picture-2"></p><p><em>Ftrace 抓取的掛起/恢復活動圖</em></p><h4 id="空閒狀態" tabindex="-1">空閒狀態 <a class="header-anchor" href="#空閒狀態" aria-label="Permalink to “空閒狀態”">​</a></h4><p>你必須確定哪個空閒狀態支持凍結。在凍結期間，電源相關代碼會決定用哪個空閒狀態來實現凍結。這個過程是通過在每個空閒狀態中查找誰定義了 <code>enter_freeze()</code> 來決定的。CPU 空閒驅動代碼或者 SoC 掛起相關代碼必須確定哪種空閒狀態實現凍結操作，並通過給每個 CPU 的可應用空閒狀態指定凍結功能來進行配置。</p><p>例如， Qualcomm 會在平台掛起代碼的掛起初始化函數處定義 <code>enter_freeze</code> 函數。這個工作是在 CPU 空閒驅動已經初始化後進行，以便所有結構已經定義就位。</p><h4 id="掛起-恢復相關驅動支持" tabindex="-1">掛起/恢復相關驅動支持 <a class="header-anchor" href="#掛起-恢復相關驅動支持" aria-label="Permalink to “掛起/恢復相關驅動支持”">​</a></h4><p>你可能會在第一次成功掛起操作後碰到驅動相關的 bug。很多驅動開發者沒有精力完全測試掛起和恢復相關的代碼。你甚至可能會發現掛起操作並沒有多少工作可做，因為 <code>pm_runtime</code> 已經做了你要做的掛起相關的一切工作。由於用户空間已經被凍結，設備此時已經處於休眠狀態並且 <code>pm_runtime</code> 已經被禁止。</p><h3 id="測試相關" tabindex="-1">測試相關 <a class="header-anchor" href="#測試相關" aria-label="Permalink to “測試相關”">​</a></h3><p>測試掛起到空閒（suspend to idle）可以手動進行，也可以使用腳本/進程等實現自動掛起、自動睡眠，或者使用像 Android 中的 <code>wakelock</code> 來讓系統掛起。如果手動測試，下面的操作會將系統凍結。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ # echo freeze &gt; /sys/power/state</span></span>
<span class="line"><span>[  142.580832] PM: Syncing filesystems … done.</span></span>
<span class="line"><span>[  142.583977] Freezing user space processes … (elapsed 0.001 seconds) done.</span></span>
<span class="line"><span>[  142.591164] Double checking all user space processes after OOM killer disable… (elapsed 0.000 seconds)</span></span>
<span class="line"><span>[  142.600444] Freezing remaining freezable tasks … (elapsed 0.001 seconds) done.</span></span>
<span class="line"><span>[  142.608073] Suspending console(s) (use no_console_suspend to debug)</span></span>
<span class="line"><span>[  142.708787] mmc1: Reset 0x1 never completed.</span></span>
<span class="line"><span>[  142.710608] msm_otg 78d9000.phy: USB in low power mode</span></span>
<span class="line"><span>[  142.711379] PM: suspend of devices complete after 102.883 msecs</span></span>
<span class="line"><span>[  142.712162] PM: late suspend of devices complete after 0.773 msecs</span></span>
<span class="line"><span>[  142.712607] PM: noirq suspend of devices complete after 0.438 msecs</span></span>
<span class="line"><span>&lt; system suspended &gt;</span></span>
<span class="line"><span>….</span></span>
<span class="line"><span>&lt; wake irq triggered &gt;</span></span>
<span class="line"><span>[  147.700522] PM: noirq resume of devices complete after 0.216 msecs</span></span>
<span class="line"><span>[  147.701004] PM: early resume of devices complete after 0.353 msecs</span></span>
<span class="line"><span>[  147.701636] msm_otg 78d9000.phy: USB exited from low power mode</span></span>
<span class="line"><span>[  147.704492] PM: resume of devices complete after 3.479 msecs</span></span>
<span class="line"><span>[  147.835599] Restarting tasks … done.</span></span>
<span class="line"><span>/ #</span></span></code></pre></div><p>在上面的例子中，需要注意 MMC 驅動的操作佔了 102.883ms 中的 100ms。有些設備驅動在掛起的時候有很多工作要做，比如將數據刷出到硬盤，或者其他耗時的操作等。</p><p>如果系統定義了凍結（freeze），那麼系統將嘗試掛起操作，如果沒有凍結功能，那麼你會看到下面的提示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ # echo freeze &gt; /sys/power/state</span></span>
<span class="line"><span>sh: write error: Invalid argument</span></span>
<span class="line"><span>/ #</span></span></code></pre></div><h3 id="未來的發展" tabindex="-1">未來的發展 <a class="header-anchor" href="#未來的發展" aria-label="Permalink to “未來的發展”">​</a></h3><p>目前在 ARM 平台上的掛起到空閒（suspend to idle）有兩方面的工作需要做。第一方面工作在前面 <code>platform_suspend_ops</code> 小節中提到過，是總允許接受凍結狀態以及合併到 4.9 版本內核中的工作。另一方面工作是凍結功能的支持。</p><p>如果你希望設備有更好的響應及表現，那麼應該繼續完善凍結功能的實現。然而，由於很多 SoC 會使用 ARM 的 CPU 空閒驅動，這使得 ARM 的 CPU 空閒驅動完善它自己的通用凍結功能的工作更有意義了。而事實上，ARM 正在嘗試添加此通用支持。如果 SoC 供應商希望實現他們自己的 CPU 空閒驅動或者需要在進入更深層次的凍結休眠狀態時提供額外的支持，那麼只有實現自己的凍結功能。</p><hr>`,34)),l("p",null,[s[6]||(s[6]=e("via: ",-1)),n(a,{href:"http://www.linaro.org/blog/suspend-to-idle/"},{default:p(()=>[...s[5]||(s[5]=[e("http://www.linaro.org/blog/suspend-to-idle/",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=e("作者：",-1)),n(a,{href:"http://www.linaro.org/author/andygross/"},{default:p(()=>[...s[7]||(s[7]=[e("Andy Gross",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),n(a,{href:"https://github.com/beyondworld"},{default:p(()=>[...s[8]||(s[8]=[e("beyondworld",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),n(a,{href:"https://github.com/jasminepeng"},{default:p(()=>[...s[9]||(s[9]=[e("jasminepeng",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const P=o(c,[["render",u]]);export{C as __pageData,P as default};
